        DaysPerWeek=4, ProgramDurationWeeks=8, MinSessionMinutes=60, MaxSessionMinutes=75, EquipmentRequired=N'Barbell, Bodyweight, Cables, Dumbbells, Exercise Ball, Machines', TargetGender=N'Female', WorkoutTypeLabel=N'Split', SourceCategoriesJson=N'["Women","Fat Loss","Beginner"]', CatalogRank=8
    WHERE SplitId=@ImportedSplitId;
