        DaysPerWeek=4, ProgramDurationWeeks=10, MinSessionMinutes=60, MaxSessionMinutes=90, EquipmentRequired=N'Barbell, Bodyweight, Cables, Dumbbells', TargetGender=N'Female', WorkoutTypeLabel=N'Split', SourceCategoriesJson=N'["Women","Muscle Building"]', CatalogRank=10
    WHERE SplitId=@ImportedSplitId;
END
