        DaysPerWeek=3, ProgramDurationWeeks=6, MinSessionMinutes=20, MaxSessionMinutes=35, EquipmentRequired=N'Bodyweight', TargetGender=N'Male & Female', WorkoutTypeLabel=N'Full Body', SourceCategoriesJson=N'["Women","Fat Loss","Full Body","Bodyweight","At Home"]', CatalogRank=19
