        DaysPerWeek=3, ProgramDurationWeeks=6, MinSessionMinutes=45, MaxSessionMinutes=45, EquipmentRequired=N'Bands, Barbell, Bodyweight, Dumbbells, Other', TargetGender=N'Female', WorkoutTypeLabel=N'Full Body', SourceCategoriesJson=N'["Women","Muscle Building","Full Body","Glutes"]', CatalogRank=24
