    SET @ImportedDayId=NEWID();
    INSERT INTO dbo.SplitDays (SplitDayId, SplitId, DayIndex, Title, FocusLabel, EstimatedMinutes, IsRestDay, SourceNotes)
    VALUES (@ImportedDayId, @ImportedSplitId, 0, N'Workout Notes', N'Single Muscle Group', 52, 0, N'Keep the rest periods short and the weight as heavy as you can go without sacrificing form. I like to keep rest intervals at 60 seconds-2 minutes max! Have any questions about this workout? Ask in the comments below and one of the team from M&S will get back to you.');
END
