WHERE SourceUrl = N'https://www.muscleandstrength.com/workouts/booty-burner-courtney-king-full-glute-workout' OR (SourceUrl IS NULL AND Name = N'Booty Burner: Courtney King''s Full Glute Workout');
IF @ImportedSplitId IS NULL
