        DaysPerWeek=3, ProgramDurationWeeks=6, MinSessionMinutes=20, MaxSessionMinutes=20, EquipmentRequired=N'Bodyweight, Dumbbells, Kettle Bells, Other', TargetGender=N'Male & Female', WorkoutTypeLabel=N'Full Body', SourceCategoriesJson=N'["Women","Fat Loss","Full Body","At Home"]', CatalogRank=42
    WHERE SplitId=@ImportedSplitId;
