SET @ImportedDayId=NULL;
SELECT @ImportedDayId=SplitDayId FROM dbo.SplitDays WHERE SplitId=@ImportedSplitId AND DayIndex=0;
IF @ImportedDayId IS NULL
BEGIN
    SET @ImportedDayId=NEWID();
    INSERT INTO dbo.SplitDays (SplitDayId, SplitId, DayIndex, Title, FocusLabel, EstimatedMinutes, IsRestDay, SourceNotes)
    VALUES (@ImportedDayId, @ImportedSplitId, 0, N'Phase 1: The First Five Minutes', N'Full Body', 20, 0, N'Start out by doing each of the exercises above following the EMOM guideline. This first phase is more for warming up and becoming familiar with the movements. You’ll perform each exercise for 20 seconds while resting for the remaining 40 seconds of that minute. Keep in mind that during your rest periods you should be transitioning to the next exercise. Here’s how that first five minutes will go.');
END
ELSE UPDATE dbo.SplitDays SET
    Title=N'Phase 1: The First Five Minutes', FocusLabel=N'Full Body', EstimatedMinutes=20, IsRestDay=0, SourceNotes=N'Start out by doing each of the exercises above following the EMOM guideline. This first phase is more for warming up and becoming familiar with the movements. You’ll perform each exercise for 20 seconds while resting for the remaining 40 seconds of that minute. Keep in mind that during your rest periods you should be transitioning to the next exercise. Here’s how that first five minutes will go.'
    WHERE SplitDayId=@ImportedDayId;
