SET @ImportedExerciseId=(SELECT TOP (1) ExerciseId FROM dbo.Exercises WHERE Name=N'Jump Rope');
IF EXISTS (SELECT 1 FROM dbo.SplitDayExercises WHERE SplitDayId=@ImportedDayId AND SortOrder=3)
    UPDATE dbo.SplitDayExercises SET
        ExerciseId=@ImportedExerciseId, TargetSets=1, TargetRepsLow=1, TargetRepsHigh=1, SourceSets=NULL, SourceReps=NULL
    WHERE SplitDayId=@ImportedDayId AND SortOrder=3;
