    INSERT INTO dbo.SplitDayExercises (SplitDayId, ExerciseId, SortOrder, TargetSets, TargetRepsLow, TargetRepsHigh, SourceSets, SourceReps)
    VALUES (@ImportedDayId, @ImportedExerciseId, 3, 1, 1, 1, NULL, NULL);
