        DaysPerWeek=5, ProgramDurationWeeks=6, MinSessionMinutes=30, MaxSessionMinutes=30, EquipmentRequired=N'Bands, Barbell, Bodyweight, Dumbbells', TargetGender=N'Female', WorkoutTypeLabel=N'Split', SourceCategoriesJson=N'["Women","Fat Loss","At Home"]', CatalogRank=44
