    VALUES (@ImportedSplitId, N'Dumbbell And Bodyweight Circuit Workout For Women', N'Calisthenics', N'Beginner', 1, N'This dumbbell workout is comprised of 10 exercises. It will work your entire body. Keep rest between exercises to a minimum, and perform each circuit 3x per training day.', N'https://cdn.muscleandstrength.com/sites/default/files/fit-woman-training-gym-with-dumbbells.jpg', 1, 1050, N'MaintainActive', N'Public', N'https://www.muscleandstrength.com/workouts/dumbbell-bodyweight-circuit-workout-women', N'Written By: M&S Writers July 9th, 2014 Updated: June 6th, 2021', N'This dumbbell workout is comprised of 10 exercises. It will work your entire body from head to toe. Keep rest between exercises to a minimum, and perform each circuit 3x per training day.', NULL, NULL, 1, 6, 30, 45, N'Bodyweight, Dumbbells', N'Female', N'Full Body', N'["Women"]', 50);
