        DaysPerWeek=4, ProgramDurationWeeks=8, MinSessionMinutes=60, MaxSessionMinutes=75, EquipmentRequired=N'Barbell, Bodyweight, Cables, Dumbbells, EZ Bar, Machines', TargetGender=N'Female', WorkoutTypeLabel=N'Split', SourceCategoriesJson=N'["Women"]', CatalogRank=58
