    VALUES (@ImportedDayId, @ImportedExerciseId, 5, 1, 20, 20, N'1', N'20');
SET @ImportedExerciseId=(SELECT TOP (1) ExerciseId FROM dbo.Exercises WHERE Name=N'Right Leg Roundhouse');
IF EXISTS (SELECT 1 FROM dbo.SplitDayExercises WHERE SplitDayId=@ImportedDayId AND SortOrder=6)
