        DaysPerWeek=4, ProgramDurationWeeks=4, MinSessionMinutes=30, MaxSessionMinutes=45, EquipmentRequired=N'Barbell, Bodyweight, Dumbbells, Exercise Ball', TargetGender=N'Female', WorkoutTypeLabel=N'Full Body', SourceCategoriesJson=N'["Women","Fat Loss"]', CatalogRank=68
