DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/chocolate-peanut-butter-protein-bars' OR (SourceUrl IS NULL AND Title=N'Chocolate And Peanut Butter Protein Bars Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Chocolate And Peanut Butter Protein Bars Recipe', N'Snack', N'These homemade protein bars taste amazing, almost like a brownie without the guilt. Main ingredients are chocolate whey protein and peanut butter.', 374, 24, 42, 8, NULL, 1, 10003, N'https://www.muscleandstrength.com/recipes/chocolate-peanut-butter-protein-bars', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/brown800.jpg', N'Makes 6 protein bars.', N'Preheat your oven to 350 degrees F. Place the oats in a blender or food processor and pulse until they reach a flour-like texture. Now place the oats in a mixing bowl and add in the cinnamon and chocolate whey protein powder. Next add in the peanut butter and mix thoroughly. Mash your bananas and add them to this mixture, along with the honey and egg whites. Mix well. Finally, add the skim milk and mix again. Pour batter into a 9x9 or 9x13 greased baking pan. You may also use a pan lined with parchment paper. Bake for 15 to 20 minutes, or until a toothpick comes out clean from the center of the pan. Allow the bars to cool and then cut into 6 bars. You may also cut them into 8 servings if you prefer a lower calories, lower protein bar. If using a 9x9 pan the bars with be a little thicker. Cooking time may vary.', N'["Protein Bar Recipes"]', N'{"calories_kcal":"374","protein_g":"23.5","carbs_g":"42","fat_g":"8"}', 313500);
END
