DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/thai-spiced-chicken.html' OR (SourceUrl IS NULL AND Title=N'Thai Spiced Chicken Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Thai Spiced Chicken Recipe', N'Snack', N'No more bland chicken breasts! This recipe combines simple seasonings and spices to make a tasty, high protein muscle building meal.', 266, 43, 8, 3, NULL, 1, 10015, N'https://www.muscleandstrength.com/recipes/thai-spiced-chicken.html', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/thai-chicken-450.jpg', N'Serves 4-5.', N'1. Preheat your oven to 375°f (350°f fan oven). Put the chicken in a shallow dish in one layer. Blend a third of the yogurt, the curry paste and three tablespoons of the cilantro. Season well with salt and pour over the chicken, turning the pieces until they are evenly coated. Leave for at least 10 minutes, or in the fridge overnight. 2. Lift the chicken on to a rack in a roasting tin and roast for 35-40 minutes, until golden. (To cook the chicken on the barbecue, reduce the cooking time to 25-30 minutes.) 3. Blend together the remaining yogurt and cilantro. Finely chop the cucumber and stir into the yogurt mixture. Season. Serve with the chicken and garnish with wedges of lime and salad greens. [Recipe adapted from original recipe found in BBC Books Good Food series: 101 Low-fat feasts]', N'["High Protein Recipes"]', N'{"calories_kcal":"266","protein_g":"43","carbs_g":"8","fat_g":"3"}', 101800);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Thai Spiced Chicken Recipe', MealType=N'Snack', Description=N'No more bland chicken breasts! This recipe combines simple seasonings and spices to make a tasty, high protein muscle building meal.', CaloriesKcal=266, ProteinG=43, CarbsG=8, FatsG=3,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10015, SourceUrl=N'https://www.muscleandstrength.com/recipes/thai-spiced-chicken.html', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/thai-chicken-450.jpg', ServingSuggestion=N'Serves 4-5.', ContentText=N'1. Preheat your oven to 375°f (350°f fan oven). Put the chicken in a shallow dish in one layer. Blend a third of the yogurt, the curry paste and three tablespoons of the cilantro. Season well with salt and pour over the chicken, turning the pieces until they are evenly coated. Leave for at least 10 minutes, or in the fridge overnight. 2. Lift the chicken on to a rack in a roasting tin and roast for 35-40 minutes, until golden. (To cook the chicken on the barbecue, reduce the cooking time to 25-30 minutes.) 3. Blend together the remaining yogurt and cilantro. Finely chop the cucumber and stir into the yogurt mixture. Season. Serve with the chicken and garnish with wedges of lime and salad greens. [Recipe adapted from original recipe found in BBC Books Good Food series: 101 Low-fat feasts]', CategoriesJson=N'["High Protein Recipes"]', SourceMacrosJson=N'{"calories_kcal":"266","protein_g":"43","carbs_g":"8","fat_g":"3"}', ReadCount=101800
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
