BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'No-Bake Gluten-Free High Protein Energy Bites Recipe', N'Snack', N'These take only about 10 minutes to put together and are packed with protein and Omega 3’s. They are great to grab on the go for a healthy high-protein snack.', 228, 17, 23, 13, NULL, 1, 10018, N'https://www.muscleandstrength.com/recipes/no-bake-protein-gluten-free-energy-bites', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/no-bake-energy-450.jpg', N'3 energy bites equals one serving.', N'In large bowl, combine Oats, Ground Chia, Hemp Seeds, Cacao Powder, Protein Powder, Cinnamon, and Sea Salt. Add in Almond Butter, Maple Syrup, Vanilla, and optional Mix-Ins, if using. Mix until just combined. Scoop 1 Tbsp of mixture and roll between hands into ball. Place on cookie sheet. Repeat until all the mixture is used. Depending on the size, this should make about 20-28. Place cookie sheet in refrigerator for about 30 minutes to set. Once chilled, store in airtight container in refrigerator for up to 1 week.', N'["Protein Bar Recipes","Snack Recipes"]', N'{"calories_kcal":"228","protein_g":"17.4","carbs_g":"23","fat_g":"12.6"}', 94800);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'No-Bake Gluten-Free High Protein Energy Bites Recipe', MealType=N'Snack', Description=N'These take only about 10 minutes to put together and are packed with protein and Omega 3’s. They are great to grab on the go for a healthy high-protein snack.', CaloriesKcal=228, ProteinG=17, CarbsG=23, FatsG=13,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10018, SourceUrl=N'https://www.muscleandstrength.com/recipes/no-bake-protein-gluten-free-energy-bites', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/no-bake-energy-450.jpg', ServingSuggestion=N'3 energy bites equals one serving.', ContentText=N'In large bowl, combine Oats, Ground Chia, Hemp Seeds, Cacao Powder, Protein Powder, Cinnamon, and Sea Salt. Add in Almond Butter, Maple Syrup, Vanilla, and optional Mix-Ins, if using. Mix until just combined. Scoop 1 Tbsp of mixture and roll between hands into ball. Place on cookie sheet. Repeat until all the mixture is used. Depending on the size, this should make about 20-28. Place cookie sheet in refrigerator for about 30 minutes to set. Once chilled, store in airtight container in refrigerator for up to 1 week.', CategoriesJson=N'["Protein Bar Recipes","Snack Recipes"]', SourceMacrosJson=N'{"calories_kcal":"228","protein_g":"17.4","carbs_g":"23","fat_g":"12.6"}', ReadCount=94800
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
