    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Rich Knapp''s Peanut Butter Cookies Recipe', N'Snack', N'A sweet, healthy and guilt-free cookie recipe used by natural bodybuilder Rich Knapp while cutting for bodybuilding contests.', 97, 4, 10, 5, NULL, 1, 10033, N'https://www.muscleandstrength.com/recipes/rich-knapps-peanut-butter-cookies.html', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/rich-knapp-cookies-450.jpg', N'Makes 36 cookies. One cookie equals one serving.', N'This peanut butter cookie recipe is prepared by Tammy Knapp, wife of natural bodybuilder Rich Knapp. Rich uses these cookies as a sweet and healthy snack while cutting for bodybuilding contests. They can be eaten without guilt, and are also a great choice when bulking or muscle building. Mix flour, protein powder, salt, baking soda and set aside. Mix applesauce and peanut butter. Add honey. Mix well and add egg whites, then beat well. Stir flour mixture into peanut butter mixture. Drop dough from tsp. onto greased baking sheet. Flatten. Bake at 375 (moderate oven) for 10 to 15 minutes until lightly browned. Makes 36 cookies.', N'["Snack Recipes"]', N'{"calories_kcal":"96.73","protein_g":"4.17","carbs_g":"10.09","fat_g":"4.99"}', 55000);
END
