    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Shaun''s Chili Recipe', N'Lunch', N'Shaun provides his daily staple...a chili recipe that will have you coming back for more.', 360, 30, 25, 16, NULL, 1, 10034, N'https://www.muscleandstrength.com/recipes/shauns-chili-recipe.html', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/shaun-chili-280.jpg', N'Makes 20 servings at slightly over 30 grams of protein each.', N'Chop and cook the onions in some oil for 10 minutes or so. Brown the meat in batches in a separate pan. When all the meat is done add to a very large pan with the onions and ad in tomatoes, mushrooms, a good amount of puree, kidney beans and chilli powder to taste. Reduce the heat and leave for a couple hours. Allow to cool then you can bag it up and freeze. Then just get one bag out each morning and it''s ready for lunch time - 3 minutes in the microwave - Easy! As long as you have the mince and tomatoes you can add pretty much anything you want in there. (Recipe nutritional information based on the addition of 4 cans of kidney beans and 2 cans of tomato puree)', N'["Lunch Recipes","Dinner Recipes"]', N'{"calories_kcal":"360","protein_g":"30.5","carbs_g":"25.4","fat_g":"15.5"}', 54600);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Shaun''s Chili Recipe', MealType=N'Lunch', Description=N'Shaun provides his daily staple...a chili recipe that will have you coming back for more.', CaloriesKcal=360, ProteinG=30, CarbsG=25, FatsG=16,
