WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/low-carb-high-protein-pumpkin-pie' OR (SourceUrl IS NULL AND Title=N'Crustless Low-Carb Protein Pumpkin Pie Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Crustless Low-Carb Protein Pumpkin Pie Recipe', N'Snack', N'Enjoying dessert, while staying on track with your meal plan was never so easy and delicious! This recipe is simple, packed with protein and the perfect way to finish off your Thanksgiving meal!', 168, 26, 11, 3, NULL, 1, 10045, N'https://www.muscleandstrength.com/recipes/low-carb-high-protein-pumpkin-pie', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/pumpkin_pie.jpg', N'Makes 6 Servings.', N'Preheat oven to 325 degrees Spray a pie dish with nonstick spray Add all ingredients of a bowl and mix well Place an oven safe dish full of water on rack below where pie will go (this prevents cracking on the top of the pie) Pour mixture into dish and bake for ~45-50 minutes or until just set Mixture will seem soft at first. Place in refrigerator to set for 4-6 hours or preferably, overnight. Top with a drizzle of fresh maple syrup or whipped cream, if desired. Notes: *Can sub with cinnamon protein powder, vanilla or even chocolate! Adjust pumpkin pie spice as needed based off of flavor used', N'["High Protein Recipes","Low Carb Recipes","Snack Recipes"]', N'{"calories_kcal":"168","protein_g":"26","carbs_g":"11","fat_g":"3"}', 46700);
END
