WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/cheesy-baked-eggplant.html' OR (SourceUrl IS NULL AND Title=N'Cheesy Baked Eggplant Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Cheesy Baked Eggplant Recipe', N'Lunch', N'Never tried cooking with eggplant? This cheesey healthy vegetarian recipe will have you coming back for more. And more!', 358, 19, 32, 19, NULL, 1, 10053, N'https://www.muscleandstrength.com/recipes/cheesy-baked-eggplant.html', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/cheesy-eggplant-450.jpg', N'Suggestion serving size is one-third of the pan.', N'Take a good sized eggplant, peel and cut into slices. Liberally apply salt. Let sit 1/2 hour. Take a paper towel and soak up the liquid that formed. Rinse thoroughly. Cut slices into quarters. Place one layer in the bottom of a 9 X 13 baking pan. Cover with 1/2 can diced tomato and one can tomato sauce. Place cheese slices over layer. Season as desired. Repeat. Bake at 350 for 45 minutes or until eggplant is as desired. This is a very low-calorie, but filling meal.', N'["Vegetarian Recipes","Lunch Recipes","Dinner Recipes"]', N'{"calories_kcal":"358","protein_g":"19","carbs_g":"32","fat_g":"19"}', 42700);
END
