WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/chocolate-peanut-butter-pancakes' OR (SourceUrl IS NULL AND Title=N'High Protein Chocolate Peanut Butter Pancakes Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'High Protein Chocolate Peanut Butter Pancakes Recipe', N'Breakfast', N'Whether you''re a fan of chocolate peanut butter or a fan of pancakes, we''ve got the perfect recipe for you! Give this delicious breakfast a shot!', 340, 42, 25, 8, NULL, 1, 10065, N'https://www.muscleandstrength.com/recipes/chocolate-peanut-butter-pancakes', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/pb-pancakes-feature.jpg', N'6 pancakes. Nutritional breakdown includes pancakes only (no toppings).', N'Preheat pan or griddle to medium/high heat. In a bowl, mix together flour, protein powder, cocoa powder, peanut flour, cinnamon, sweetener, and baking powder. Add one egg yolk, milk, and vanilla extract. Gently stir together until combined. In a separate bowl, add three egg whites. Whisk with a hand mixer until stiff peaks. Add egg whites to pancake batter. Gently fold egg whites into batter. Be careful not to over mix or the egg whites will lose their volume and fluffiness. Spoon batter evenly onto preheated griddle to make about 6 medium sized pancakes. Cook for a few minutes or until the middles of the pancakes start to bubble then flip. Cook for another few minutes on the other side. * If using regular peanut butter in the batter, add into batter when you add the wet ingredients. If using peanut flour, add when you mix the dry ingredients.', N'["High Protein Recipes","Snack Recipes","Breakfast Recipes"]', N'{"calories_kcal":"340","protein_g":"42","carbs_g":"25","fat_g":"8"}', 37000);
END
