INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'½ cup black beans, drained and rinsed');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'½ cup frozen corn');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 7, N'⅓ cup shredded Mexican cheese');
