INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Heat a large nonstick skillet over medium heat. Add in your chicken and cook 2-3 minutes.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Add remaining ingredients except cheese to the chicken. Stir and allow to simmer for 5 minutes.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Evenly divide filling between pepper halves. Top with shredded cheese.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'Cover baking dish with foil and cook for 30-35 minutes or until cheese has melted.');
