INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Place potatoes on a baking sheet and bake for about 1 hour or until tender');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'While potatoes are cooking, boil chicken for about 8-10 minutes or until cooked through');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'When chicken is done, shred it by using 2 forks');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'Toss the chicken with the BBQ sauce and set aside');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 8, N'When potatoes are done, remove from the oven and allow to cool enough to handle');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 9, N'Cut the potatoes in half and scoop out the middle, leaving a small bit of potato along the sides');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 10, N'Evenly divide the pulled BBQ chicken among the potatoes');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 11, N'Sprinkle with shredded cheddar cheese');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 12, N'Return to the oven and bake an additional 20 minutes or until cheese is melted');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 13, N'Finish off with extra BBQ sauce, if desired');
GO

