INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 12, N'Sea Salt & Pepper to taste');
DELETE FROM dbo.MealSuggestionInstructions WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 1, N'Preheat oven to 300F');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'Add oil to saute pan and set on medium-high heat');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'Season chicken with salt, pepper and desired seasonings. Italian seasoning is my personal choice!');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Once oil is close to reaching its smoke-point (or when you see ripples in oil), add chicken and sear each side until golden brown. Remove from pan and put on baking sheet and into the oven');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Place saute pan back onto heat and start deglazing pan with tomatoes. After a few seconds, add garlic, mushrooms, and snow peas. Saute until fragrant and mushrooms are golden brown. Deglaze again with white wine and let cook until all wine has dissipated');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Add milk and reduce by half, then add Arrowroot (mixed into a slurry with some water) and thicken until desired consistency is reached');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'Remove chicken from oven when internal temperature of 160F is reached. Let rest until it reaches 165F');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 8, N'While chicken rests, toss spaghetti squash into sauce');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 9, N'Serve baked chicken on top of sauced spaghetti squash and enjoy!');
