DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/healthy-protein-strawberry-toaster-strudel' OR (SourceUrl IS NULL AND Title=N'Healthy, High Protein Strawberry Toaster Strudel Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Healthy, High Protein Strawberry Toaster Strudel Recipe', N'Breakfast', N'This healthy, high protein alternative tastes exactly like a toaster strudel. Seriously! Coming in at only 114 calories and 17 grams of protein, it''s a perfect low cal option.', 114, 17, 10, 4, NULL, 1, 10120, N'https://www.muscleandstrength.com/recipes/healthy-protein-strawberry-toaster-strudel', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/strawberry-450.jpg', N'Makes one serving.', N'Method: Lay out tortilla. Microwave berries and then smash. Add whey protein to strawberries and mix well. Put berry mix in center of tortilla. Fold in sides and top to form a rectangle toaster strudel (use some protein mixed with water as a glue to hold flaps closed). Grill on a George Forman grill for a few minutes, so the outside gets crispy! (Or you could wrap it in parchment paper and put it in an actual toaster, but watch to make sure the paper doesn''t burn!) Mix casein and water - put into a ziplock bag and cut a small corner off. Once toaster strudel is done, pipe the casein mix on top! Let it cool a bit or you''ll burn yourself eating this deliciousness. It seriously tasted exactly like a strawberry toaster strudel.. especially if you let it get crispy enough! If you don''t have casein protein you can always use my go to sweet little mix: 1 TBS whey protein 1 TBS coconut flour 3 TBS water! Enjoy!', N'["High Protein Recipes","Breakfast Recipes"]', N'{"calories_kcal":"114","protein_g":"17","carbs_g":"10.5","fat_g":"4.3"}', 18700);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Healthy, High Protein Strawberry Toaster Strudel Recipe', MealType=N'Breakfast', Description=N'This healthy, high protein alternative tastes exactly like a toaster strudel. Seriously! Coming in at only 114 calories and 17 grams of protein, it''s a perfect low cal option.', CaloriesKcal=114, ProteinG=17, CarbsG=10, FatsG=4,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10120, SourceUrl=N'https://www.muscleandstrength.com/recipes/healthy-protein-strawberry-toaster-strudel', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/strawberry-450.jpg', ServingSuggestion=N'Makes one serving.', ContentText=N'Method: Lay out tortilla. Microwave berries and then smash. Add whey protein to strawberries and mix well. Put berry mix in center of tortilla. Fold in sides and top to form a rectangle toaster strudel (use some protein mixed with water as a glue to hold flaps closed). Grill on a George Forman grill for a few minutes, so the outside gets crispy! (Or you could wrap it in parchment paper and put it in an actual toaster, but watch to make sure the paper doesn''t burn!) Mix casein and water - put into a ziplock bag and cut a small corner off. Once toaster strudel is done, pipe the casein mix on top! Let it cool a bit or you''ll burn yourself eating this deliciousness. It seriously tasted exactly like a strawberry toaster strudel.. especially if you let it get crispy enough! If you don''t have casein protein you can always use my go to sweet little mix: 1 TBS whey protein 1 TBS coconut flour 3 TBS water! Enjoy!', CategoriesJson=N'["High Protein Recipes","Breakfast Recipes"]', SourceMacrosJson=N'{"calories_kcal":"114","protein_g":"17","carbs_g":"10.5","fat_g":"4.3"}', ReadCount=18700
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'1 Costco low carb high fiber tortilla');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'4 small strawberries');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'1/4 scoop Muscle Gauge Nutrition vanilla whey protein powder');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'1/4 scoop Micellar Casein Protein mixed with water until creamy texture');
DELETE FROM dbo.MealSuggestionInstructions WHERE MealSuggestionId=@ImportedMealSuggestionId;
GO

