INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'8 extra thin corn tortillas*');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'Chipotle seasoning, as desired');
