DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/apple-turnover' OR (SourceUrl IS NULL AND Title=N'Healthy & Delicious Apple Turnover Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Healthy & Delicious Apple Turnover Recipe', N'Breakfast', N'Treat yourself to something sweet utilizing this recipe for healthy apple turnovers. Pair it with your favorite protein for the perfect post workout snack!', 357, 6, 50, 19, NULL, 1, 10138, N'https://www.muscleandstrength.com/recipes/apple-turnover', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/apple-turnover-feature.jpg', N'Makes 4 turnovers. 1 Serving = 1 turnover', N'Preheat oven to 400 degrees F Combine xylitol, cinnamon and cornstarch in a bowl. Set aside. Melt coconut oil in a skillet over medium heat. Add in apples and mix well. Allow to cook for 3-4 minutes. Add dry ingredients into apple mixture and mix until all apples are coated. Allow to cook until sauce thickens. Remove from heat and set aside. Unfold pastry sheets and cut into four squares. Spoon apples into center of each pastry sheet. Fold over from corner to corner, creating a triangle shape. Press edges down with a fork to seal in apples. Place on a parchment lined baking sheet. Using a pastry brush, brush the top of each turnover with the egg whites and sprinkle with additional xylitol, if using. Bake for about 20 minutes or until golden. Allow to cool slightly before enjoying! Notes: *Use the larger quantity of xylitol if you prefer your turnovers on the sweeter side. *These turnovers are very big! Feel free to create 8 smaller ones instead. Please note that the baking time for 8 turnovers should be adjusted to around 12 minutes. *Pair with your favorite protein shake to up the protein content for a perfect postworkout or morning snack!', N'["Snack Recipes","Vegetarian Recipes","Breakfast Recipes"]', N'{"calories_kcal":"357","protein_g":"6","carbs_g":"50","fat_g":"19"}', 16200);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Healthy & Delicious Apple Turnover Recipe', MealType=N'Breakfast', Description=N'Treat yourself to something sweet utilizing this recipe for healthy apple turnovers. Pair it with your favorite protein for the perfect post workout snack!', CaloriesKcal=357, ProteinG=6, CarbsG=50, FatsG=19,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10138, SourceUrl=N'https://www.muscleandstrength.com/recipes/apple-turnover', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/apple-turnover-feature.jpg', ServingSuggestion=N'Makes 4 turnovers. 1 Serving = 1 turnover', ContentText=N'Preheat oven to 400 degrees F Combine xylitol, cinnamon and cornstarch in a bowl. Set aside. Melt coconut oil in a skillet over medium heat. Add in apples and mix well. Allow to cook for 3-4 minutes. Add dry ingredients into apple mixture and mix until all apples are coated. Allow to cook until sauce thickens. Remove from heat and set aside. Unfold pastry sheets and cut into four squares. Spoon apples into center of each pastry sheet. Fold over from corner to corner, creating a triangle shape. Press edges down with a fork to seal in apples. Place on a parchment lined baking sheet. Using a pastry brush, brush the top of each turnover with the egg whites and sprinkle with additional xylitol, if using. Bake for about 20 minutes or until golden. Allow to cool slightly before enjoying! Notes: *Use the larger quantity of xylitol if you prefer your turnovers on the sweeter side. *These turnovers are very big! Feel free to create 8 smaller ones instead. Please note that the baking time for 8 turnovers should be adjusted to around 12 minutes. *Pair with your favorite protein shake to up the protein content for a perfect postworkout or morning snack!', CategoriesJson=N'["Snack Recipes","Vegetarian Recipes","Breakfast Recipes"]', SourceMacrosJson=N'{"calories_kcal":"357","protein_g":"6","carbs_g":"50","fat_g":"19"}', ReadCount=16200
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
