    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Protein Gingerbread Men Cookie Recipe', N'Snack', N'Get festive for the holidays and hit your macros at the same time! These high protein gingerbread cookies are not only fun & festive, but also healthy!', 203, 8, 16, 13, NULL, 1, 10141, N'https://www.muscleandstrength.com/recipes/protein-gingerbread-cookies', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/protein-gingerbread-feature.jpg', N'Makes 8 servings.', N'Combine first 8 ingredients together in a mixing bowl. Whisk together molasses, coconut oil and egg. Combine wet and dry ingredients. Place dough in the refrigerator for 30 minutes to chill. After 30 minutes, remove your dough. Flour your rolling surface and rolling pin very well. Roll dough to about ½ in thick. Cut into desired shape with cookie cutter. Place cookies on a parchment lined baking sheet. Place cookie sheet in the refrigerator for 20 minutes. Preheat oven to 375 degrees Fahrenheit. Bake cookies for 8-10 minutes (for large cookies) or 6-8 minutes (for small cookies) or until golden. Decorate as desired. Notes: Can be made into 16 small cookies if desired. Macros for small cookies (undecorated) are 102cals, 4g protein, 8g carbohydrates, and 7g of fat.', N'["High Protein Recipes","Snack Recipes","Vegetarian Recipes"]', N'{"calories_kcal":"203","protein_g":"8","carbs_g":"16","fat_g":"13"}', 16000);
END
