WHERE SourceUrl=N'https://www.muscleandstrength.com/recipe/red-white-blue-pancakes' OR (SourceUrl IS NULL AND Title=N'High Protein Red, White & Blue Pancakes Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'High Protein Red, White & Blue Pancakes Recipe', N'Breakfast', N'Ring in the 4th of July with a healthy stack of high-protein pancakes that are topped with fresh summer blueberries and raspberries!', 497, 52, 59, 6, NULL, 1, 10144, N'https://www.muscleandstrength.com/recipe/red-white-blue-pancakes', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/rwb_pancakes.jpg', N'Macronutrients based on entire recipe.', N'Whisk together oat flour, coconut flour, protein powder and baking powder. In a second bowl mix together egg whites, greek yogurt, vanilla extract and sweetener, if using. Combine wet and dry ingredients. Divide the batter into 2 bowls and mix blueberries into one and raspberries into the other.* Coat skillet with oil or non stick spray. Heat pan over medium heat. Spoon batter into heated skillet. Cook until small bubbles begin to form. Flip and cook for an additional 1-1.5 minutes. Repeat until all batter is cooked. Stack pancakes alternating between blueberry and raspberry for a red, white and blue effect. Top as desired. Note: You can leave the berries out of the batter and serve on top, if preferred.', N'["High Protein Recipes","Breakfast Recipes"]', N'{"calories_kcal":"497","protein_g":"52.2","carbs_g":"59.3","fat_g":"5.8"}', 15800);
END
