INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'The next day, add your special k cereal to a food processor and blend into small pieces (conversely, you can add to a Ziploc back and crush by hand)');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Put the cereal, cornmeal, paprika, salt and pepper in a Ziploc bag');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Preheat oven to 400 degrees');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Line a baking sheet with parchment paper');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 7, N'Remove chicken, one piece at a time, from the marinating bag and add to cereal mixture');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 8, N'Shake until coated');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 9, N'Repeat with all chicken');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 10, N'Place coated chicken on baking sheet');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 11, N'Bake for 20 minutes');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 12, N'Reduce heat to 350 degrees and bake for an additional 15 minutes or until crispy');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 13, N'While chicken is cooking, make waffles according to directions');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 14, N'Serve chicken on top of waffles');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 15, N'Add syrup and butter for a more authentic experience, if desired');
GO

DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/soft-serve-protein-ice-cream-recipe' OR (SourceUrl IS NULL AND Title=N'Soft Serve Protein Ice Cream Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Soft Serve Protein Ice Cream Recipe', N'Snack', N'Time to try a guilt-free, high protein ice cream recipe that you will love! All you need is whey protein, almond milk, ice and salt. 26 grams of protein and only 170 calories.', 170, 26, 9, 2, NULL, 1, 10163, N'https://www.muscleandstrength.com/recipes/soft-serve-protein-ice-cream-recipe', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/ice-cream-450.jpg', N'Makes one serving.', N'Add the protein and milk to the small ziplock - mix it a bit and zip closed. Place the smaller ziplock into the larger one full of ice. Pour salt into the big bag [but NOT into the ingredient one!] Now SHAKE WHATCHA MOMMA GAVE YA! Shake for about 2-4 minutes until frozen. Maaaybe you should wear gloves, cuz it gets COLDDDD. And viola! Soft serve ice cream :] Feel free to add toppings like fruit, peanut butter, cocoa to make it chocolate, nuts, coconut shreds, etc.', N'["Snack Recipes"]', N'{"calories_kcal":"170","protein_g":"26","carbs_g":"9","fat_g":"2.5"}', 13100);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Soft Serve Protein Ice Cream Recipe', MealType=N'Snack', Description=N'Time to try a guilt-free, high protein ice cream recipe that you will love! All you need is whey protein, almond milk, ice and salt. 26 grams of protein and only 170 calories.', CaloriesKcal=170, ProteinG=26, CarbsG=9, FatsG=2,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10163, SourceUrl=N'https://www.muscleandstrength.com/recipes/soft-serve-protein-ice-cream-recipe', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/ice-cream-450.jpg', ServingSuggestion=N'Makes one serving.', ContentText=N'Add the protein and milk to the small ziplock - mix it a bit and zip closed. Place the smaller ziplock into the larger one full of ice. Pour salt into the big bag [but NOT into the ingredient one!] Now SHAKE WHATCHA MOMMA GAVE YA! Shake for about 2-4 minutes until frozen. Maaaybe you should wear gloves, cuz it gets COLDDDD. And viola! Soft serve ice cream :] Feel free to add toppings like fruit, peanut butter, cocoa to make it chocolate, nuts, coconut shreds, etc.', CategoriesJson=N'["Snack Recipes"]', SourceMacrosJson=N'{"calories_kcal":"170","protein_g":"26","carbs_g":"9","fat_g":"2.5"}', ReadCount=13100
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'1 large ziplock bag filled with iced');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'1 sandwich sized ziplock');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'1 scoop whey protein [I used Muscle Gauge Ice Cream Sandwich!]');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'1 cup almond milk');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'1/2 cup salt');
DELETE FROM dbo.MealSuggestionInstructions WHERE MealSuggestionId=@ImportedMealSuggestionId;
GO

