    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'The Perfect Curry Tuna Melt (With Jicama Fries!) Recipe', N'Lunch', N'It’s that time of year where comfort food cravings are high! Satisfy them in a high protein, low carb and flavorful way with this simple tuna melt recipe!', 399, 54, 32, 9, NULL, 1, 10164, N'https://www.muscleandstrength.com/recipes/perfect-curry-tuna-melt-jicama-fries', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/tuna_melt_recipe_with_jicama_fries.jpg', N'Makes 2 Servings.', N'Preheat oven to 425 Toss together jicama, oil and seasoning Spread on baking sheet Bake for 20 minutes Toss Bake for an additional 20 minutes or until golden While fries are baking, mix together tuna, yogurt, curry spice and chives Divide tuna evenly between 2 slices of bread Place a slice of cheese on top of each sandwich Top with additional slice of bread Place in oven with fries for last 3 minutes of cooking or until cheese is melted Divide fries evenly between 2 plates and serve each with 1 sandwich Serve with a protein shake on the side for a sweet, comfort food finish', N'["High Protein Recipes","Lunch Recipes"]', N'{"calories_kcal":"399","protein_g":"54","carbs_g":"32","fat_g":"9"}', 13100);
END
