WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/cafe-cream-protein-truffles' OR (SourceUrl IS NULL AND Title=N'Delicious & Easy Café Cream Protein Truffles Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Delicious & Easy Café Cream Protein Truffles Recipe', N'Snack', N'Curb your chocolate cravings with this perfect bite-sized snack that not only packs delicious coffee flavor, but delivers protein as well!', 128, 4, 10, 8, NULL, 1, 10172, N'https://www.muscleandstrength.com/recipes/cafe-cream-protein-truffles', N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/protein_truffles.jpg', NULL, N'Mix all of the ingredients together, except the Sweet Spreads CocoNutter. Shape your dough into desired size truffle bites. Line a baking sheet with parchment paper. Melt your Sweet Spreads CocoNutter. Roll each truffle into the melted CocoNutter. Place the truffles on baking sheet and refrigerate for about 1 hour, or until chocolate is fully set.', N'["Snack Recipes"]', N'{"calories_kcal":"128","protein_g":"3.5","carbs_g":"10.2","fat_g":"8.3"}', 12400);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Delicious & Easy Café Cream Protein Truffles Recipe', MealType=N'Snack', Description=N'Curb your chocolate cravings with this perfect bite-sized snack that not only packs delicious coffee flavor, but delivers protein as well!', CaloriesKcal=128, ProteinG=4, CarbsG=10, FatsG=8,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10172, SourceUrl=N'https://www.muscleandstrength.com/recipes/cafe-cream-protein-truffles', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/image/recipe/protein_truffles.jpg', ServingSuggestion=NULL, ContentText=N'Mix all of the ingredients together, except the Sweet Spreads CocoNutter. Shape your dough into desired size truffle bites. Line a baking sheet with parchment paper. Melt your Sweet Spreads CocoNutter. Roll each truffle into the melted CocoNutter. Place the truffles on baking sheet and refrigerate for about 1 hour, or until chocolate is fully set.', CategoriesJson=N'["Snack Recipes"]', SourceMacrosJson=N'{"calories_kcal":"128","protein_g":"3.5","carbs_g":"10.2","fat_g":"8.3"}', ReadCount=12400
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
DELETE FROM dbo.MealSuggestionIngredients WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 1, N'2/3 Scoop (30g) Nutriforce Sports Cafe Cream Protein');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'6 tbsp. (42g) Coconut flour');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'2 tbsp. (28g) coconut oil');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 4, N'2 tbsp. (42g) honey (or sweetener of choice)');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 5, N'3 tbsp. (42g) Sweet Spreads Chocolate Brownie Coconutter');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'1/2 tsp. coffee extract, optional');
DELETE FROM dbo.MealSuggestionInstructions WHERE MealSuggestionId=@ImportedMealSuggestionId;
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 1, N'Mix all of the ingredients together, except the Sweet Spreads CocoNutter.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 2, N'Shape your dough into desired size truffle bites.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 3, N'Line a baking sheet with parchment paper.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 4, N'Melt your Sweet Spreads CocoNutter.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 5, N'Roll each truffle into the melted CocoNutter.');
INSERT INTO dbo.MealSuggestionInstructions (MealSuggestionId, SortOrder, InstructionText) VALUES (@ImportedMealSuggestionId, 6, N'Place the truffles on baking sheet and refrigerate for about 1 hour, or until chocolate is fully set.');
GO

