INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 6, N'1.5 cup Blue Diamond Unsweetened Almond Coconut Milk (Silk Almond Milk can be used as well)');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 7, N'126g (1/2 cup) Unsweetened Natural Applesauce');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 8, N'50g Egg White or 1 Whole Egg (50g is equivalent to 1 Large Whole Egg)');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 9, N'3tbs 100% Pure Maple Syrup');
