INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 2, N'⅔ cups (80g) Oat Flour');
INSERT INTO dbo.MealSuggestionIngredients (MealSuggestionId, SortOrder, IngredientText) VALUES (@ImportedMealSuggestionId, 3, N'2 tbsp. (14g) Coconut Flour');
