DECLARE @ImportedMealSuggestionId UNIQUEIDENTIFIER;
SELECT TOP (1) @ImportedMealSuggestionId=MealSuggestionId FROM dbo.MealSuggestions
WHERE SourceUrl=N'https://www.muscleandstrength.com/recipes/sesame-cranbutter-sirloin-steak-tip-skewers' OR (SourceUrl IS NULL AND Title=N'Sesame CranButter Sirloin Steak Tip Skewers Recipe');
IF @ImportedMealSuggestionId IS NULL
BEGIN
    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Sesame CranButter Sirloin Steak Tip Skewers Recipe', N'Dinner', N'Keep your carbs low and the flavor high with this simple protein-packed steak recipe that can be made in large batches to enjoy throughout the week!', 274, 34, 10, 10, NULL, 1, 10181, N'https://www.muscleandstrength.com/recipes/sesame-cranbutter-sirloin-steak-tip-skewers', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/ss_feature.jpg', N'Makes 4 servings.', N'Mix together your sesame cranbutter, liquid aminos (soy sauce), garlic and hot water. Cut sirloin steak into desired size strips or chunks. Place steak and ½ marinade in a ziplock bag and place in the refrigerator for 3-4 hours (or overnight). While steak is marinating, soak skewers in water (if using wood skewers). Remove meat and thread onto skewers. Cook on indoor or outside grill to desired doneness. Served with remaining marinade as a dipping sauce. Note: Would be great with a side of brown rice and steamed broccoli for a well-rounded meal.', N'["Dinner Recipes","BBQ/Grill Recipes"]', N'{"calories_kcal":"274","protein_g":"33.6","carbs_g":"10.2","fat_g":"10.4"}', 11500);
END
ELSE UPDATE dbo.MealSuggestions SET
    Title=N'Sesame CranButter Sirloin Steak Tip Skewers Recipe', MealType=N'Dinner', Description=N'Keep your carbs low and the flavor high with this simple protein-packed steak recipe that can be made in large batches to enjoy throughout the week!', CaloriesKcal=274, ProteinG=34, CarbsG=10, FatsG=10,
    SuggestedMonth=NULL, IsSystemDefault=1, SortOrder=10181, SourceUrl=N'https://www.muscleandstrength.com/recipes/sesame-cranbutter-sirloin-steak-tip-skewers', ImageUrl=N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/ss_feature.jpg', ServingSuggestion=N'Makes 4 servings.', ContentText=N'Mix together your sesame cranbutter, liquid aminos (soy sauce), garlic and hot water. Cut sirloin steak into desired size strips or chunks. Place steak and ½ marinade in a ziplock bag and place in the refrigerator for 3-4 hours (or overnight). While steak is marinating, soak skewers in water (if using wood skewers). Remove meat and thread onto skewers. Cook on indoor or outside grill to desired doneness. Served with remaining marinade as a dipping sauce. Note: Would be great with a side of brown rice and steamed broccoli for a well-rounded meal.', CategoriesJson=N'["Dinner Recipes","BBQ/Grill Recipes"]', SourceMacrosJson=N'{"calories_kcal":"274","protein_g":"33.6","carbs_g":"10.2","fat_g":"10.4"}', ReadCount=11500
    WHERE MealSuggestionId=@ImportedMealSuggestionId;
