    SET @ImportedMealSuggestionId=NEWID();
    INSERT INTO dbo.MealSuggestions
        (MealSuggestionId, Title, MealType, Description, CaloriesKcal, ProteinG, CarbsG, FatsG, SuggestedMonth, IsSystemDefault, SortOrder, SourceUrl, ImageUrl, ServingSuggestion, ContentText, CategoriesJson, SourceMacrosJson, ReadCount)
    VALUES (@ImportedMealSuggestionId, N'Mini Coconut Chocolate Chip Protein Cookies Recipe', N'Snack', N'Get your coconut fix with these protein-filled mini cookies that combine chocolate and coconut so deliciously you''ll forget they''re good for you as well!', 60, 2, 4, 4, NULL, 1, 10185, N'https://www.muscleandstrength.com/recipes/mini-chocolate-coconut-protein-cookies', N'https://cdn.muscleandstrength.com/sites/default/files/field/feature-image/recipe/mini_chocolate_chip_coconut_protein_cookies_2.jpg', N'Nutrition facts based on 1 cookie', N'Preheat oven to 325 degrees Line a baking sheet with parchment paper Sift together dry ingredients: whey protein, coconut flour, oat flour, baking soda and salt Whisk together wet ingredients: egg whites, coconut milk, coconut oil, stevia and vanilla Combine wet and dry ingredients Fold in shredded coconut and chocolate chips Drop batter onto parchment paper in tablespoon size servings Bake for ~12 minutes or until slightly golden (will still feel soft) Allow to sit for 20 minutes Frost with chocolate peanut butter, if desired Notes: * I have not tried this recipe with a reduced fat or fat free milk ** I used 40 drops of liquid stevia. Please adjust based on sweetness of protein powder used *** Feel free to add in more or less shredded coconut and chocolate chips, as desired', N'["Snack Recipes"]', N'{"calories_kcal":"60","protein_g":"2.5","carbs_g":"3.6","fat_g":"4.3"}', 10800);
END
